{"content": "1|import ArchiveDomain
2|import ArchiveSecurity
3|import CMinizipBridge
4|import Foundation
5|
6|public actor ZIPArchiveProvider: ArchiveProvider {
7|    private var reader: ZIPBridgeReader?
8|    private var entriesByID: [ArchiveEntryID: ArchiveEntrySnapshot] = [:]
9|    private var ordinalsByID: [ArchiveEntryID: UInt64] = [:]
10|
11|    public init() {}
12|
13|    public func open(url: URL) throws -> ArchiveDocumentSnapshot {
14|        reader = nil
15|        entriesByID = [:]
16|        ordinalsByID = [:]
17|
18|        let openedReader = try ZIPBridgeReader(url: url)
19|        let bridgeEntries = try openedReader.allEntries()
20|        var snapshots: [ArchiveEntrySnapshot] = []
21|        snapshots.reserveCapacity(bridgeEntries.count)
22|
23|        for bridgeEntry in bridgeEntries {
24|            guard let displayPath = String(bytes: bridgeEntry.nameBytes, encoding: .utf8) else {
25|                throw ArchiveError.unsupportedFormat
26|            }
27|            if !bridgeEntry.isDirectory {
28|                do {
29|                    try ArchivePathPolicy().validate(displayPath)
30|                } catch {
31|                    throw ArchiveError.unsafePath
32|                }
33|            }
34|
35|            let entry = ArchiveEntry(
36|                id: ArchiveEntryID(),
37|                rawPath: ArchivePathBytes(bridgeEntry.nameBytes),
38|                displayPath: displayPath
39|            )
40|            snapshots.append(ArchiveEntrySnapshot(
41|                entry: entry,
42|                compressedSize: bridgeEntry.compressedSize,
43|                uncompressedSize: bridgeEntry.uncompressedSize,
44|                modifiedAt: bridgeEntry.modifiedAt,
45|                isDirectory: bridgeEntry.isDirectory,
46|                isSymbolicLink: bridgeEntry.isSymbolicLink,
47|                isEncrypted: bridgeEntry.isEncrypted,
48|                usesUTF8FileName: bridgeEntry.usesUTF8FileName
49|            ))
50|        }
51|
52|        reader = openedReader
53|        entriesByID = Dictionary(uniqueKeysWithValues: snapshots.map { ($0.entry.id, $0) })
54|        ordinalsByID = Dictionary(uniqueKeysWithValues: snapshots.enumerated().map {
55|            ($0.element.entry.id, UInt64($0.offset))
56|        })
57|        return ArchiveDocumentSnapshot(sourceURL: url, format: .zip, entries: snapshots)
58|    }
59|
60|    public func readEntry(id: ArchiveEntryID, maximumBytes: UInt64) throws -> Data {
61|        guard
62|            let snapshot = entriesByID[id],
63|            let ordinal = ordinalsByID[id],
64|            let reader
65|        else {
66|            throw ArchiveError.helperFailed
67|        }
68|        guard !snapshot.isDirectory, !snapshot.isSymbolicLink else {
69|            throw ArchiveError.unsafePath
70|        }
71|        guard snapshot.uncompressedSize <= maximumBytes,
72|              snapshot.uncompressedSize <= UInt64(Int.max) else {
73|            throw ArchiveError.resourceLimit
74|        }
75|        return try reader.readEntry(
76|            ordinal: ordinal,
77|            expectedSize: snapshot.uncompressedSize,
78|            maximumBytes: maximumBytes
79|        )
80|    }
81|
82|    public func materializeEntry(
83|        id: ArchiveEntryID,
84|        under rootURL: URL,
85|        budget: ResourceBudget = .previewDefault
86|    ) throws -> URL {
87|        guard let snapshot = entriesByID[id] else {
88|            throw ArchiveError.helperFailed
89|        }
90|        let decision = budget.evaluate(ResourceEstimate(
91|            compressedBytes: snapshot.compressedSize,
92|            expandedBytes: snapshot.uncompressedSize,
93|            entries: 1,
94|            depth: 1
95|        ))
96|        guard decision == .allow else { throw ArchiveError.resourceLimit }
97|        let data = try readEntry(id: id, maximumBytes: budget.maxExpandedBytes)
98|        return try SecureFileMaterializer(rootURL: rootURL).write(
99|            data,
100|            relativePath: snapshot.entry.displayPath
101|        )
102|    }
103|}
104|
105|private struct ZIPBridgeEntry {
106|    let nameBytes: [UInt8]
107|    let compressedSize: UInt64
108|    let uncompressedSize: UInt64
109|    let modifiedAt: Date?
110|    let isDirectory: Bool
111|    let isSymbolicLink: Bool
112|    let isEncrypted: Bool
113|    let usesUTF8FileName: Bool
114|}
115|
116|private final class ZIPBridgeReader {
117|    private var handle: OpaquePointer?
118|
119|    init(url: URL) throws {
120|        var opened: OpaquePointer?
121|        let status = url.withUnsafeFileSystemRepresentation { path in
122|            guard let path else { return Int32(AWB_MZ_INVALID_ARGUMENT) }
123|            return awb_mz_reader_open(path, &opened)
124|        }
125|        guard status == AWB_MZ_OK, let opened else {
126|            throw ZIPProviderErrorMapper.archiveError(for: status)
127|        }
128|        handle = opened
129|    }
130|
131|    deinit {
132|        awb_mz_reader_close(&handle)
133|    }
134|
135|    func allEntries() throws -> [ZIPBridgeEntry] {
136|        guard let handle else { throw ArchiveError.helperFailed }
137|        var result: [ZIPBridgeEntry] = []
138|        var info = awb_mz_entry_info()
139|        var status = awb_mz_reader_first(handle, &info)
140|        while status == AWB_MZ_OK {
141|            result.append(try copy(info))
142|            status = awb_mz_reader_next(handle, &info)
143|        }
144|        guard status == AWB_MZ_END else {
145|            throw ZIPProviderErrorMapper.archiveError(for: status)
146|        }
147|        return result
148|    }
149|
150|    func readEntry(ordinal: UInt64, expectedSize: UInt64, maximumBytes: UInt64) throws -> Data {
151|        guard let handle else { throw ArchiveError.helperFailed }
152|        var info = awb_mz_entry_info()
153|        var status = awb_mz_reader_goto(handle, ordinal, &info)
154|        guard status == AWB_MZ_OK else {
155|            throw ZIPProviderErrorMapper.archiveError(for: status)
156|        }
157|        status = awb_mz_reader_open_current(handle)
158|        guard status == AWB_MZ_OK else {
159|            throw ZIPProviderErrorMapper.archiveError(for: status)
160|        }
161|
162|        var data = Data()
163|        data.reserveCapacity(Int(expectedSize))
164|        var buffer = [UInt8](repeating: 0, count: 64 * 1024)
165|        var readError: ArchiveError?
166|        while true {
167|            let count = buffer.withUnsafeMutableBufferPointer { bytes in
168|                awb_mz_reader_read_current(handle, bytes.baseAddress, Int32(bytes.count))
169|            }
170|            if count == 0 { break }
171|            if count < 0 {
172|                readError = ZIPProviderErrorMapper.archiveError(for: count)
173|                break
174|            }
175|            let nextSize = UInt64(data.count) + UInt64(count)
176|            if nextSize > maximumBytes {
177|                readError = .resourceLimit
178|                break
179|            }
180|            data.append(buffer, count: Int(count))
181|        }
182|
183|        let closeStatus = awb_mz_reader_close_current(handle)
184|        if let readError { throw readError }
185|        guard closeStatus == AWB_MZ_OK else {
186|            throw ZIPProviderErrorMapper.archiveError(for: closeStatus)
187|        }
188|        guard UInt64(data.count) == expectedSize else {
189|            throw ArchiveError.corruptedArchive
190|        }
191|        return data
192|    }
193|
194|    private func copy(_ info: awb_mz_entry_info) throws -> ZIPBridgeEntry {
195|        guard let nameBytes = info.name_bytes, info.name_size > 0 else {
196|            throw ArchiveError.corruptedArchive
197|        }
198|        let name = Array(UnsafeBufferPointer(start: nameBytes, count: Int(info.name_size)))
199|        return ZIPBridgeEntry(
200|            nameBytes: name,
201|            compressedSize: info.compressed_size,
202|            uncompressedSize: info.uncompressed_size,
203|            modifiedAt: info.modified_unix_time > 0
204|                ? Date(timeIntervalSince1970: TimeInterval(info.modified_unix_time))
205|                : nil,
206|            isDirectory: info.is_directory != 0,
207|            isSymbolicLink: info.is_symlink != 0,
208|            isEncrypted: info.is_encrypted != 0,
209|            usesUTF8FileName: info.uses_utf8_file_name != 0
210|        )
211|    }
