15|extension ZIPArchiveProvider {
16|    public func createWindowsZIP(at outputURL: URL, inputs: [URL]) throws {
17|        guard !FileManager.default.fileExists(atPath: outputURL.path) else {
18|            throw WindowsZIPProfileError.outputExists
19|        }
20|        let files = try WindowsZIPPreflight().collect(inputs: inputs)
21|        let stageURL = outputURL.deletingLastPathComponent().appending(
22|            path: "." + outputURL.lastPathComponent + ".staging-" + UUID().uuidString
23|        )
24|        var stageExists = false
25|        defer {
26|            if stageExists { try? FileManager.default.removeItem(at: stageURL) }
27|        }
28|
29|        let writer = try ZIPBridgeWriter(url: stageURL)
30|        stageExists = true
31|        for file in files {
32|            try writer.add(sourceURL: file.sourceURL, archivePath: file.archivePath)
33|        }
34|        for file in files {
35|            guard try file.fingerprint == SourceFingerprint(url: file.sourceURL) else {
36|                throw ArchiveError.sourceChanged
37|            }
38|        }
